#!/usr/bin/env bash
# Regenerates app/src/main/res/layout/widget_layout_<font>.xml, one per font style.
# Widgets can't change font family at runtime (no RemoteViews method for it), so each
# font needs its own layout. Edit the template below, not the generated files.
set -euo pipefail
cd "$(dirname "$0")/../app/src/main/res/layout"

fonts=(Default Thin Light Medium Black CondensedLight Condensed Serif Monospace Typewriter Casual Cursive SmallCaps)

clock() { # id weight gravity visibility style format12 format24 textSize
    cat <<XML
        <TextClock
            android:id="@+id/$1"
            style="@style/ClockStyle.$5"
            android:layout_weight="$2"
            android:format12Hour="$6"
            android:format24Hour="$7"
            android:gravity="$3"
            android:textSize="$8"
            android:visibility="$4" />
XML
}

for font in "${fonts[@]}"; do
    file="widget_layout_${font,,}.xml"
    {
        cat <<XML
<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/generate_widget_layouts.sh. Do not edit by hand. -->
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"
    android:id="@+id/clock_frame"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:layout_marginHorizontal="@dimen/widget_margin"
    android:layout_marginVertical="@dimen/widget_margin_vertical"
    android:gravity="center"
    android:orientation="vertical">

    <LinearLayout
        android:layout_width="match_parent"
        android:layout_height="wrap_content"
        android:orientation="horizontal">
XML
        clock clockLeft 1 "center_vertical|start" gone "$font" "h:mm" "H:mm" 42sp
        clock clock 2 center visible "$font" "h:mm" "H:mm" 42sp
        clock clockRight 1 "center_vertical|end" gone "$font" "h:mm" "H:mm" 42sp
        cat <<XML
    </LinearLayout>

    <LinearLayout
        android:layout_width="match_parent"
        android:layout_height="wrap_content"
        android:orientation="horizontal">
XML
        clock dateLeft 1 "center_vertical|start" gone "$font" "EEE, MMM d" "EEE, MMM d" 22sp
        clock date 1 center visible "$font" "EEE, MMM d" "EEE, MMM d" 22sp
        clock dateRight 1 "center_vertical|end" gone "$font" "EEE, MMM d" "EEE, MMM d" 22sp
        cat <<XML
    </LinearLayout>
</LinearLayout>
XML
    } > "$file"
done
echo "generated ${#fonts[@]} layouts"
